def impute(s, X, method):
    labs = s['lab_id']
    strata = s['stratum']
    (_, i, n) = np.unique(np.c_[labs, strata], axis=0, return_inverse=True, return_counts=True)
    w = 1 / n[i, None]
    mu = np.nansum(w * X, 0) / np.sum(w * np.isfinite(X), 0)
    result = X.copy()
    for (a, j) in zip(*np.where(~np.isfinite(X))):
        masks = {'cell': (labs == labs[a]) & (strata == strata[a]), 'lab': labs == labs[a], 'stratum': strata == strata[a], 'unweighted': np.ones(len(X), bool)}
        if method in masks:
            v = X[masks[method], j]
            result[a, j] = np.nanmean(v) if np.isfinite(v).any() else mu[j]
        else:
            result[a, j] = {'zero': 0.0, 'balanced': mu[j], 'raw_balanced': mu[j]}[method]
    if method == 'raw_balanced':
        rr = s['coupon_features_raw']
        v = np.nansum(w * rr, 0) / np.sum(w * np.isfinite(rr), 0)
        for (a, j) in zip(*np.where(~np.isfinite(X))):
